sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var gr = new GlideRecord("sys_attachment");
        gr.addQuery('table_name', 'x_hsb11_mss_trus_0_complaint_case'); // Filter by table name
        gr.addQuery('table_sys_id', current.sys_id); // Filter by the current record's sys_id
        gr.query();

        var attachCount = 0;
        var maxSize = 5 * 1024 * 1024; // 5MB in bytes

        while (gr.next()) {
            attachCount++;
            if (attachCount > 1) {
                gs.addErrorMessage('More than one attachment found. Aborting action.');
                current.setAbortAction(true); // Abort if more than one attachment
                break;
            }

            if (gr.size_bytes > maxSize) {
                gs.addErrorMessage('Attachment size exceeds 5MB. Aborting action.');
                current.setAbortAction(true); // Abort if attachment size exceeds 5MB
                break;
            }
        }
    } catch (error) {
        // Log the error for debugging
        gs.error('An error occurred in the Business Rule: ' + error.message);
        current.setAbortAction(true); // Abort the action to prevent further processing
    }
})(current, previous);
